per_call.cmd:
cat > /etc/nginx/sites-available/vnc.conf << 'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;

    root /var/www/html;
    index index.html;

    server_name _;

    # VNC WebSocket proxy
    location /vnc {
        proxy_pass http://127.0.0.1:5901;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }

    # Main page
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
ln -sf /etc/nginx/sites-available/vnc.conf /etc/nginx/sites-enabled/vnc.conf
rm -f /etc/nginx/sites-enabled/default
nginx -t 2>&1

cd /var/www/html && cat > index.html << 'HTMLEOF'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Windows 3.11 VNC Console</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            background: #333;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
        }
        #screen {
            background: #000;
            width: 800px;
            height: 600px;
        }
    </style>
</head>
<body>
    <canvas id="screen"></canvas>
    <script src="https://unpkg.com/@novnc/novnc@1.5.0/core/rfb.js"></script>
    <script>
        const canvas = document.getElementById('screen');
        const rfb = new RFB(canvas, 'ws://' + window.location.host + '/vnc');
        rfb.viewOnly = false;
        rfb.scaleViewport = true;
        rfb.shared = true;
        rfb.addEventListener('connect', () => console.log('Connected to VNC'));
        rfb.addEventListener('disconnect', (e) => console.log('Disconnected', e.detail));
    </script>
</body>
</html>
HTMLEOF
cat index.html | head -30

cat > /etc/nginx/sites-available/vnc.conf << 'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;

    root /var/www/html;
    index index.html;

    server_name _;

    # VNC WebSocket proxy (QEMU uses port 6080 for websocket)
    location /vnc {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }

    # Main page
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
nginx -t 2>&1 && service nginx reload

cat > /etc/nginx/sites-available/vnc.conf << 'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;

    root /var/www/html;
    index index.html;

    server_name _;

    # VNC WebSocket proxy (QEMU uses port 6080 for websocket)
    location /vnc {
        proxy_pass http://127.0.0.1:6080/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }

    # Main page
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
nginx -t && service nginx reload
curl -I http://localhost/vnc 2>&1

cat > /etc/nginx/nginx.conf << 'EOF'
user  root;
worker_processes  1;


events {
    worker_connections 4096;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    # Sending fille Optimization
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;

    # Keepalive Connection
    keepalive_timeout 65;

    include /etc/nginx/sites-enabled/*;
}
EOF
nginx -t && service nginx reload
curl -I http://localhost/ 2>&1
